// Welches Modell soll antworten? Ein "anbieter_override" aus dem
// aufrufenden Workflow hat Vorrang vor der Standard-Einstellung.
const e = $('⚙️ Modell-Einstellungen').first().json;
// Reihenfolge: 1. Vorgabe des aufrufenden Workflows, 2. Schalter auf der Ergebnis-Seite
// ("lokal" / "claude"), 3. anbieter_standard hier im Einstellungs-Knoten.
const schalter = $json.ki_ort === 'claude' ? 'claude' : $json.ki_ort === 'lokal' ? 'ollama' : '';
// 0. Höchste Priorität: Modell-Auswahl pro Funktion aus "⚙️ Einstellungen" (Profil)
// Neue Funktionen ohne gespeicherte Auswahl erben von einer verwandten (statt auf lokal zu fallen)
const ERBT_VON = { einordnung: 'fakten' };
const wahl = ($json.modelle || {})[e.funktion] || ($json.modelle || {})[ERBT_VON[e.funktion]] || null;
const wahlAnbieter = wahl && wahl.anbieter ? (wahl.anbieter === 'lokal' ? 'ollama' : wahl.anbieter) : '';
const anbieter = String(wahlAnbieter || e.anbieter_override || schalter || e.anbieter_standard || 'claude').toLowerCase().trim();

// Modelle haben ein begrenztes "Kontextfenster" (wie viel Text sie auf einmal
// lesen können). Deshalb kürzen wir den Seitentext auf höchstens N Wörter.
const maxWoerter = Number(anbieter === 'ollama' ? e.max_woerter_ollama : e.max_woerter_claude) || 2000;
const text = String(e.seitentext || '');
let ende = text.length;
let gezaehlt = 0;
const wort = /\S+/g;
let m;
while ((m = wort.exec(text)) !== null) {
  gezaehlt++;
  if (gezaehlt === maxWoerter) {
    ende = m.index + m[0].length;
    break;
  }
}
const gekuerzt = ende < text.length;
const eingefuegt = text.slice(0, ende) + (gekuerzt ? '\n[... Text nach ' + maxWoerter + ' Wörtern gekürzt ...]' : '');
const voll = String(e.anfrage || '').replace('{{SEITENTEXT}}', () => eingefuegt);
// Prompt Caching (nur Claude): Alles VOR der Zeile <<<CACHE>>> ist bei jeder Stelle gleich
// (Anweisung, Such-Prompt, Lebenslauf). Claude merkt sich diesen Anfang ca. 5 Minuten –
// jede weitere Stelle zahlt dafür nur ~10 %. Andere Anbieter bekommen den Text ohne Marke.
const MARKE = /\n?<<<CACHE>>>\n?/;
const teile = voll.split(MARKE);
const anfrage_fest = teile.length > 1 ? teile[0] + '\n\n' : '';
const anfrage_rest = teile.length > 1 ? teile.slice(1).join('\n') : voll;
const anfrage = anfrage_fest + anfrage_rest;

return {
  json: {
    anbieter,
    // Ein aufrufender Workflow kann auch Modell und effort vorgeben (z. B. C: Sonnet).
    // "claude_modell_zwang" (vom aufrufenden Workflow pro Stelle) schlägt alles – nur wenn ohnehin Claude antwortet
    modell: e.claude_modell_zwang && anbieter === 'claude' ? e.claude_modell_zwang :
      wahl && wahl.modell && wahlAnbieter === anbieter
        ? wahl.modell
        : anbieter === 'claude'
          ? e.claude_modell_override || e.claude_modell
          : anbieter === 'ollama'
            ? e.ollama_modell_override || e.ollama_modell
            : (wahl && wahl.modell) || '',
    funktion: e.funktion || '',
    system: e.system,
    anfrage,
    anfrage_fest,
    anfrage_rest,
    schema: e.schema,
    claude_effort: e.claude_effort_override || e.claude_effort,
    ollama_url: e.ollama_url,
    ollama_kontext: e.ollama_kontext,
    ollama_denken: e.ollama_denken_override || e.ollama_denken,
    gekuerzt,
    start_ms: Date.now(),
    kontext: e.kontext || {},
  },
};

// Beide Modelle antworten in einem anderen "Umschlag":
//   Claude:  { content: [ { type: 'text', text: '{...}' } ], stop_reason, usage }
//   Ollama:  { message: { content: '{...}' }, eval_count, ... }
// Hier holen wir den JSON-Text heraus und wandeln ihn in ein Objekt um.
const req = $('Anfrage vorbereiten').first().json;
const r = $json;
const dauer_s = Math.round((Date.now() - req.start_ms) / 100) / 10;
let roh = '';
let fehler = '';

if (r.error) {
  fehler = typeof r.error === 'string' ? r.error : r.error.message || JSON.stringify(r.error);
} else if (req.anbieter === 'claude') {
  if (r.stop_reason === 'refusal') fehler = 'Claude hat die Anfrage abgelehnt (refusal).';
  if (r.stop_reason === 'max_tokens') fehler = 'Antwort wurde abgeschnitten (max_tokens zu klein).';
  const block = (r.content || []).find((b) => b.type === 'text');
  roh = block ? block.text : '';
} else if (req.anbieter === 'openai' || req.anbieter === 'mistral') {
  //   OpenAI/Mistral: { choices: [ { message: { content: '{...}' }, finish_reason } ], usage }
  const c = (r.choices || [])[0] || {};
  const msg = c.message || {};
  if (msg.refusal) fehler = 'Modell hat die Anfrage abgelehnt: ' + msg.refusal;
  if (c.finish_reason === 'length') fehler = 'Antwort wurde abgeschnitten (zu lang).';
  roh = Array.isArray(msg.content) ? msg.content.map((t) => t.text || '').join('') : String(msg.content || '');
} else if (req.anbieter === 'gemini') {
  //   Gemini: { candidates: [ { content: { parts: [ { text: '{...}' } ] }, finishReason } ], usageMetadata }
  const c = (r.candidates || [])[0] || {};
  if (c.finishReason === 'MAX_TOKENS') fehler = 'Antwort wurde abgeschnitten (zu lang).';
  if (!c.content && r.promptFeedback && r.promptFeedback.blockReason) fehler = 'Gemini hat die Anfrage blockiert: ' + r.promptFeedback.blockReason;
  roh = ((c.content || {}).parts || []).map((p) => p.text || '').join('');
} else {
  roh = (r.message && r.message.content) || '';
}

let daten = null;
if (!fehler) {
  try {
    const sauber = roh
      .replace(/<think>[\s\S]*?<\/think>/g, '')
      .replace(/^\s*```(json)?/, '')
      .replace(/```\s*$/, '')
      .trim();
    daten = JSON.parse(sauber);
  } catch (e) {
    fehler = 'Antwort war kein gültiges JSON: ' + roh.slice(0, 300);
  }
}

// Probleme, bei denen jede weitere Anfrage auch scheitert → Seite meldet es, Lauf hält an
let problem = '';
const NAME = { claude: 'Claude', openai: 'OpenAI', gemini: 'Gemini', mistral: 'Mistral' }[req.anbieter] || req.anbieter;
if (/credit balance|purchase credits|billing|insufficient_quota|exceeded your current quota/i.test(fehler)) {
  problem = 'guthaben';
  fehler = `${NAME}-Guthaben ist leer – beim Anbieter nachladen. (` + fehler.slice(0, 200) + ')';
} else if (/authentication_error|invalid x-api-key|invalid_api_key|API_KEY_INVALID|API key not valid|Unauthorized|Authorization failed|\b401\b/i.test(fehler)) {
  problem = 'schluessel';
  fehler = `${NAME}: API-Schlüssel ungültig – in n8n → Credentials prüfen. (` + fehler.slice(0, 200) + ')';
}

return {
  json: {
    ok: !fehler && daten !== null,
    daten,
    fehler,
    problem,
    anbieter: req.anbieter,
    modell: req.modell,
    dauer_s,
    gekuerzt: req.gekuerzt,
    verbrauch: r.usage || r.usageMetadata || (r.eval_count ? { eingabe_tokens: r.prompt_eval_count, ausgabe_tokens: r.eval_count } : null),
    kontext: req.kontext,
  },
};
